#!/usr/bin/env bash
# Automated Windows installation + provisioning for the builder VM.
#
#   bash scripts/qemu/install-windows.sh        (or: just build-windows-install)
#
# Idempotent: if the guest already answers on SSH, reports ready and exits.
#
# Two answer-file modes:
#  * USER MODE (preferred): .vm/windows-builder/autounattend.xml provided by
#    the user (e.g. generated by schneegans.de). Used verbatim; our
#    provisioning (sshd/git/uv/SSH key) rides along via $OEM$/$$/Setup/Scripts
#    on the ISO root, which the schneegans PE script copies into the image.
#    Completion is detected by SSH coming up (SetupComplete ran), then a grace
#    period lets first-logon scripts finish before shutdown.
#  * TEMPLATE MODE (fallback): our unattend template + SetupComplete with a
#    final shutdown; completion detected by the VM powering off.
#
# Needs beforehand: Windows ISO at .vm/windows-builder/windows.iso and host
# packages from scripts/qemu/README.md.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
# shellcheck source=common.sh
source "$SCRIPT_DIR/common.sh"

UNATTEND_SRC="$SCRIPT_DIR/unattend"
UNATTEND_BUILD="$AGIO_VM_DIR/unattend-build"
UNATTEND_ISO="$AGIO_VM_DIR/unattend.iso"
USER_UNATTEND="$AGIO_VM_DIR/autounattend.xml"
REPO_UNATTEND="$UNATTEND_SRC/windows-ltsc-autounattend.xml"
# image index for TEMPLATE MODE only: 6 = Pro on standard consumer ISOs
AGIO_WIN_IMAGE_INDEX="${AGIO_WIN_IMAGE_INDEX:-6}"
AGIO_INSTALL_TIMEOUT="${AGIO_INSTALL_TIMEOUT:-5400}"       # 90 min
# first-logon scripts (tweaks, virtio guest tools) grace after SSH is up
AGIO_VM_POSTINSTALL_GRACE="${AGIO_VM_POSTINSTALL_GRACE:-600}"

step() { echo; echo "=== $* ==="; }

step "State check"
if vm_ssh_reachable; then
    echo "Windows already installed, SSH works. Nothing to do."
    echo "Build: bash scripts/qemu/build-windows-qemu.sh   (just build-windows)"
    exit 0
fi
if vm_is_running || vm_port_in_use; then
    echo "[ERROR] VM or port $AGIO_VM_SSH_PORT is busy. Stop it first:"
    echo "        bash scripts/qemu/build-windows-qemu.sh --shutdown"
    exit 1
fi

step "Prerequisites"
for bin in "$AGIO_QEMU_BIN" qemu-img swtpm genisoimage socat; do
    if ! command -v "$bin" >/dev/null 2>&1; then
        echo "[ERROR] $bin not found."
        echo "        sudo apt install qemu-system-x86 qemu-utils ovmf swtpm swtpm-tools genisoimage socat"
        exit 1
    fi
done
if ! ls /dev/kvm >/dev/null 2>&1; then
    echo "[WARN] /dev/kvm not available - installation will be VERY slow."
fi
for f in "$AGIO_OVMF_CODE" "$AGIO_OVMF_VARS_SRC"; do
    [ -f "$f" ] || { echo "[ERROR] OVMF firmware missing: $f (apt install ovmf)"; exit 1; }
done
if [ ! -f "$AGIO_WIN_ISO" ]; then
    echo "[ERROR] Windows ISO not found: $AGIO_WIN_ISO"
    echo "        Download an x64 ISO (activation not needed for builds) and"
    echo "        save/link it as $AGIO_WIN_ISO (see .vm/windows-builder/README.txt)"
    exit 1
fi

mkdir -p "$AGIO_VM_DIR"

if [ ! -f "$AGIO_VM_KEY" ]; then
    ssh-keygen -t ed25519 -N "" -C "agio-win-builder" -f "$AGIO_VM_KEY" >/dev/null
    echo "Generated SSH key: $AGIO_VM_KEY"
fi
PUBKEY="$(cat "$AGIO_VM_PUBKEY")"

step "Prepare install media"
if [ ! -f "$AGIO_VIRTIO_ISO" ]; then
    echo "Downloading virtio-win.iso (~700 MB)..."
    curl -fL --retry 3 -o "$AGIO_VIRTIO_ISO.part" "$AGIO_VIRTIO_URL"
    mv "$AGIO_VIRTIO_ISO.part" "$AGIO_VIRTIO_ISO"
fi

rm -rf "$UNATTEND_BUILD"
mkdir -p "$UNATTEND_BUILD"
OEM_SCRIPTS_DIR="$UNATTEND_BUILD/sources/\$OEM\$/\$\$/Setup/Scripts"

ANSWER_FILE=""
if [ -f "$USER_UNATTEND" ]; then
    ANSWER_FILE="$USER_UNATTEND"
elif [ -f "$REPO_UNATTEND" ]; then
    ANSWER_FILE="$REPO_UNATTEND"
fi

if [ -n "$ANSWER_FILE" ]; then
    echo "Using user-provided answer file: $ANSWER_FILE"
    cp "$ANSWER_FILE" "$UNATTEND_BUILD/autounattend.xml"
    # schneegans PE script picks $OEM$ up from the ISO ROOT
    OEM_SCRIPTS_DIR="$UNATTEND_BUILD/\$OEM\$/\$\$/Setup/Scripts"
else
    echo "No user answer file - using built-in template (user: $AGIO_VM_USER)"
    # Sanity-check the image index: custom ISOs often hold a single image.
    if command -v 7z >/dev/null 2>&1; then
        tmpd="$(mktemp -d)"
        7z e -y -o"$tmpd" "$AGIO_WIN_ISO" sources/install.esd >/dev/null 2>&1 || true
        [ -f "$tmpd/install.esd" ] || \
            7z e -y -o"$tmpd" "$AGIO_WIN_ISO" sources/install.wim >/dev/null 2>&1 || true
        img_file="$(ls "$tmpd"/* 2>/dev/null | head -1)"
        if [ -n "$img_file" ]; then
            images="$(7z l "$img_file" 2>/dev/null | sed -n 's/^Images = \([0-9][0-9]*\)$/\1/p' | head -1)"
            if [ -n "$images" ] && [ "$AGIO_WIN_IMAGE_INDEX" -gt "$images" ]; then
                echo "[WARN] image index $AGIO_WIN_IMAGE_INDEX not in this ISO ($images image(s) found) - using index 1"
                AGIO_WIN_IMAGE_INDEX=1
            fi
        fi
        rm -rf "$tmpd"
    fi
    sed -e "s|{{IMAGE_INDEX}}|$AGIO_WIN_IMAGE_INDEX|g" \
        -e "s|{{VM_PASSWORD}}|$AGIO_VM_PASSWORD|g" \
        "$UNATTEND_SRC/autounattend.xml.tmpl" > "$UNATTEND_BUILD/autounattend.xml"
fi

mkdir -p "$OEM_SCRIPTS_DIR"
sed -e "s|{{SSH_PUBLIC_KEY}}|$PUBKEY|g" -e "s|{{VM_USER}}|$AGIO_VM_USER|g" \
    "$UNATTEND_SRC/SetupComplete.cmd.tmpl" > "$OEM_SCRIPTS_DIR/SetupComplete.cmd"
sed -e "s|{{SSH_PUBLIC_KEY}}|$PUBKEY|g" -e "s|{{VM_USER}}|$AGIO_VM_USER|g" \
    "$UNATTEND_SRC/SetupComplete.ps1.tmpl" > "$OEM_SCRIPTS_DIR/SetupComplete.ps1"
genisoimage -quiet -J -V AGIOUNATT -o "$UNATTEND_ISO" "$UNATTEND_BUILD"
echo "Unattend ISO: $UNATTEND_ISO"

step "Create fresh disk"
if [ -f "$AGIO_VM_DISK" ]; then
    echo "[WARN] removing existing unprovisioned disk: $AGIO_VM_DISK"
    rm -f "$AGIO_VM_DISK" "$AGIO_OVMF_VARS"
fi
qemu-img create -f qcow2 "$AGIO_VM_DISK" "$AGIO_VM_DISK_SIZE" >/dev/null
cp "$AGIO_OVMF_VARS_SRC" "$AGIO_OVMF_VARS"

step "Unattended Windows install"
echo "Nothing to click. Watch progress with a VNC client at 127.0.0.1:5902"
echo "Timeout: $((AGIO_INSTALL_TIMEOUT / 60)) min. Waiting for guest SSH..."
start_swtpm
# shellcheck disable=SC2086
"$AGIO_QEMU_BIN" $(qemu_base_args) \
    -display none -vnc 127.0.0.1:2 \
    -daemonize -pidfile "$AGIO_VM_DIR/qemu.pid" \
    -drive id=cdwin,if=none,media=cdrom,file="$AGIO_WIN_ISO" \
    -device ide-cd,bus=ide.0,drive=cdwin,bootindex=1 \
    -drive id=cdunatt,if=none,media=cdrom,file="$UNATTEND_ISO" \
    -device ide-cd,bus=ide.1,drive=cdunatt,bootindex=2 \
    -drive id=cdvirt,if=none,media=cdrom,file="$AGIO_VIRTIO_ISO" \
    -device ide-cd,bus=ide.2,drive=cdvirt

INSTALL_PID="$(cat "$AGIO_VM_DIR/qemu.pid")"

# Windows install media shows "Press any key to boot from CD or DVD" on the
# first boot; nobody is at the console, so feed it a key via the QEMU monitor.
# (Mid-install reboots boot from disk - bootindex 0 - and need no key.)
echo "Feeding CD-boot keypress via monitor..."
for _ in $(seq 1 15); do
    echo 'sendkey spc' | socat - "unix-connect:$AGIO_VM_DIR/monitor.sock" >/dev/null 2>&1 || true
    sleep 3
done

deadline=$((SECONDS + AGIO_INSTALL_TIMEOUT))
last_report=0
while true; do
    if ! kill -0 "$INSTALL_PID" 2>/dev/null; then
        echo "[ERROR] QEMU exited before the guest answered on SSH."
        echo "        Check VNC 127.0.0.1:5902 next run; guest log (if any):"
        echo "        C:\\Windows\\Temp\\agio-setupcomplete.log"
        rm -f "$AGIO_VM_DIR/qemu.pid"
        stop_swtpm
        exit 1
    fi
    if vm_ssh_reachable; then
        echo "Guest SSH is up - provisioning ran."
        break
    fi
    if [ $SECONDS -ge $deadline ]; then
        echo "[ERROR] no SSH within $((AGIO_INSTALL_TIMEOUT / 60)) min."
        echo "        Check VNC 127.0.0.1:5902; guest log:"
        echo "        C:\\Windows\\Temp\\agio-setupcomplete.log"
        kill "$INSTALL_PID" 2>/dev/null || true
        rm -f "$AGIO_VM_DIR/qemu.pid"
        stop_swtpm
        exit 1
    fi
    if [ $((SECONDS - last_report)) -ge 60 ]; then
        echo "  ... installing ($((SECONDS / 60)) min elapsed)"
        last_report=$SECONDS
    fi
    sleep 10
done

echo "--- Checking build tools in guest ---"
TOOLS_OK=1
ssh_vm 'where git.exe' >/dev/null 2>&1 || { echo "[WARN] git.exe not in guest PATH"; TOOLS_OK=0; }
ssh_vm 'where uv.exe'  >/dev/null 2>&1 || { echo "[WARN] uv.exe not in guest PATH"; TOOLS_OK=0; }
if [ "$TOOLS_OK" -eq 1 ]; then
    echo "git: $(ssh_vm 'git --version')"
    echo "uv:  $(ssh_vm 'uv --version')"
fi

echo "--- Grace period for first-logon scripts ($((AGIO_VM_POSTINSTALL_GRACE / 60)) min) ---"
sleep "$AGIO_VM_POSTINSTALL_GRACE"

shutdown_vm

echo
echo "=== Windows VM installed and provisioned. ==="
echo "Build now:  bash scripts/qemu/build-windows-qemu.sh   (just build-windows)"
if [ "$TOOLS_OK" -ne 1 ]; then
    echo "[WARN] some tools were missing - boot with GUI (--boot) and check"
    echo "       C:\\Windows\\Temp\\agio-setupcomplete.log"
fi
